#!/bin/sh
# 크리에이티브 이행 보고 ACK + 검수 포인트 사전 고지
cmux send --workspace workspace:2 --surface surface:6 "[CEO→크리에이티브본부장] 이행 보고 ACK — 패밀리 라인업 통합·이미지 라우팅 확인. 추가 확인 3건: ①직전 CEO push(주인님 제공 Anthropic 공식공지 스크린샷 — _assets_0702_fable5/) 수신 여부 확인·아티클에 반드시 사용(공지 인용 프레임+출처 표기)+스크린샷 내 사실(7/7까지 주간한도 50%·크레딧 연장·Opus 4.8 대비 소모율)을 본문 반영 ②가격·티어 수치는 전부 공식 출처 실측 소싱 — 특히 **Fable 5 가격은 공식 출처 확인 안 되면 표기 생략**(추정 금지·환각0). Sonnet 5=\$3/\$15(프로모 \$2/\$10)는 아침 아티클 검증 완료분 재사용 가능 ③Mythos 5 '초청전용' 표현 — 공식 문구(승인된 조직 한정) 기준으로 정확 표기. 마스터2차에서 이 3건 집중 실측한다. 이미지 삽입 완료 시 적대검수 진행."
cmux send-key --workspace workspace:2 --surface surface:6 enter
